const body = $('Will Submission Webhook').item.json.body || $('Will Submission Webhook').item.json;
const driveFolder = $('Create Client Submission Folder in Google Drive').item.json;
const driveFile = $('Upload Will Document to Google Drive').item.json;

const now = new Date();
const dateStr = now.toISOString();

const refId = body.refId || ('VBL-' + Math.floor(100000 + Math.random() * 900000));
const fullName = body.fullName || 'Anonymous Client';
const phone = body.phone || '';
const email = body.email || '';
const serviceType = body.serviceType || 'draft_new';
const city = body.city || 'Kavali';

const driveFolderId = driveFolder.id;
const driveFolderName = driveFolder.name || (refId + ' - ' + fullName);
const driveFolderUrl = driveFolder.webViewLink || ('https://drive.google.com/drive/folders/' + driveFolderId);
const driveUrl = driveFile.webViewLink || ('https://drive.google.com/file/d/' + driveFile.id + '/view');

return [{
  json: {
    refId,
    fullName,
    phone,
    email,
    serviceType,
    city,
    dateStr,
    driveFolderId,
    driveFolderName,
    driveFolderUrl,
    driveUrl,
    status: 'New Submission',
    alertSubject: '⚖️ New Will Submission: ' + fullName + ' (' + refId + ')',
    alertBody: 'A new confidential will drafting submission has been received and organized in Google Drive.\n\n' +
      'Client: ' + fullName + '\n' +
      'Phone: ' + phone + '\n' +
      'Email: ' + email + '\n' +
      'City: ' + city + '\n' +
      'Service: ' + serviceType + '\n' +
      'Google Drive Client Folder: ' + driveFolderUrl + '\n' +
      'Google Drive Document: ' + driveUrl + '\n\n' +
      'Chambers Portal: https://vbllawchambers.com/chambers-portal'
  }
}];
